#include <vector>

using namespace std;

class Solution {
public:
    int minMoves(vector<int>& nums, int limit) {
        vector<int> diff(2 * limit + 2);
        int n = nums.size();
        for (int i = 0; i < n / 2; ++i) {
            int a = nums[i], b = nums[n - 1 - i];
            int l = min(a, b) + 1, r = max(a, b) + limit;
            diff[2] += 2;
            diff[l] -= 1;
            diff[a + b] -= 1;
            diff[a + b + 1] += 1;
            diff[r + 1] += 1;
        }

        int res = n, curr = 0;
        for (int i = 2; i <= 2 * limit; ++i) {
            curr += diff[i];
            res = min(res, curr);
        }
        return res;
    }
};
